begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_column('public','people','gender','family member profile can store gender');
select has_column('public','people','date_of_birth','family member profile can store date of birth');
select has_column('public','people','health_condition','each person has a separate health note');
select has_column('public','people','health_status','each person can select a health status');
select has_column('public','people','health_details','each person can enter health details');
select has_column('public','families','father_national_id','father has a national ID field');
select has_column('public','families','mother_national_id','mother has a national ID field');
select has_column('public','families','father_health_condition','father has a separate health note');
select has_column('public','families','mother_health_condition','mother has a separate health note');
select has_column('public','families','father_health_status','father can select a health status');
select has_column('public','families','mother_health_status','mother can select a health status');
select has_column('public','families','father_employment_status','father can select employment status');
select has_column('public','families','mother_employment_status','mother can select employment status');
select has_column('public','families','father_occupation','father work type is stored');
select has_column('public','families','mother_occupation','mother work type is stored');
select has_column('public','people','employment_status','each member can select employment status');
select has_column('public','people','occupation','each member work type is stored');
insert into auth.users(id) values ('63000000-0000-0000-0000-000000000001'),('63000000-0000-0000-0000-000000000002');
insert into auth.sessions(id,user_id,created_at,updated_at) values ('73000000-0000-0000-0000-000000000001','63000000-0000-0000-0000-000000000001',now(),now()),('73000000-0000-0000-0000-000000000002','63000000-0000-0000-0000-000000000002',now(),now());
insert into public.employees(id,employee_code,display_name,role) values ('83000000-0000-0000-0000-000000000001','AGEW','Writer','employee'),('83000000-0000-0000-0000-000000000002','AGER','Reader','employee');
insert into private.employee_auth(employee_id,auth_user_id) values ('83000000-0000-0000-0000-000000000001','63000000-0000-0000-0000-000000000001'),('83000000-0000-0000-0000-000000000002','63000000-0000-0000-0000-000000000002');
insert into public.employee_permissions(employee_id,cases_read,cases_write) values ('83000000-0000-0000-0000-000000000001',true,true),('83000000-0000-0000-0000-000000000002',true,false);
insert into public.families(id,name,phone) values ('94000000-0000-0000-0000-000000000001','أسرة اختبار بيانات السن','01012345678');
select set_config('request.jwt.claims','{"sub":"63000000-0000-0000-0000-000000000001","session_id":"73000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.add_family_member_profile('94000000-0000-0000-0000-000000000001','ريم','بنت','female','2008-12-31')$$,'writer adds member with gender and date of birth');
select lives_ok($$select public.add_family_member_profile('94000000-0000-0000-0000-000000000001','كريم','ابن','male','2010-05-01','مرض','حساسية صدر')$$,'new member RPC saves health status and details');
select lives_ok($$select public.add_family_member_profile('94000000-0000-0000-0000-000000000001','سلمى','بنت','female','2012-06-01',null,null,'يعمل','مدرسة')$$,'new member RPC saves employment status and work type');
select is((select gender from public.people where name='ريم'),'female'::text,'writer saves member gender');
select is((select date_of_birth from public.people where name='ريم'),'2008-12-31'::date,'writer saves member date of birth');
select is((select to_jsonb(p)->>'health_status' from public.people p where name='كريم'),'مرض','individual health status persists');
select is((select to_jsonb(p)->>'health_details' from public.people p where name='كريم'),'حساسية صدر','individual health details persist');
select is((select to_jsonb(p)->>'employment_status' from public.people p where name='سلمى'),'يعمل','individual employment status persists');
select is((select to_jsonb(p)->>'occupation' from public.people p where name='سلمى'),'مدرسة','individual work type persists');
select lives_ok($$update public.people set health_status='عجز أو إعاقة',health_details='إعاقة حركية',health_condition='إعاقة حركية' where name='كريم'$$,'writer can update individual health status and details');
select is((select to_jsonb(p)->>'health_status' from public.people p where name='كريم'),'عجز أو إعاقة','updated individual health status persists');
select lives_ok($$select public.save_case_file('94000000-0000-0000-0000-000000000001','{"mother_name":"الأم","phone":"01012345678","father_national_id":"28001011234567","mother_national_id":"29001011234567","father_health_status":"مستقرة","mother_health_status":"مرض","mother_health_condition":"ضغط","mother_employment_status":"يعمل","mother_occupation":"خياطة","father_employment_status":"لا يعمل"}'::jsonb,null)$$,'writer saves parent identity, health and employment data');
select is((select to_jsonb(f)->>'father_national_id' from public.families f where id='94000000-0000-0000-0000-000000000001'),'28001011234567','father national ID persists');
select is((select to_jsonb(f)->>'mother_national_id' from public.families f where id='94000000-0000-0000-0000-000000000001'),'29001011234567','mother national ID persists');
select is((select to_jsonb(f)->>'father_health_condition' from public.families f where id='94000000-0000-0000-0000-000000000001'),null,'stable father has no extra condition details');
select is((select to_jsonb(f)->>'mother_health_condition' from public.families f where id='94000000-0000-0000-0000-000000000001'),'ضغط','mother health note persists');
select is((select to_jsonb(f)->>'father_health_status' from public.families f where id='94000000-0000-0000-0000-000000000001'),'مستقرة','father health status persists');
select is((select to_jsonb(f)->>'mother_health_status' from public.families f where id='94000000-0000-0000-0000-000000000001'),'مرض','mother health status persists');
select is((select to_jsonb(f)->>'mother_employment_status' from public.families f where id='94000000-0000-0000-0000-000000000001'),'يعمل','mother employment status persists');
select is((select to_jsonb(f)->>'mother_occupation' from public.families f where id='94000000-0000-0000-0000-000000000001'),'خياطة','mother work type persists');
select is((select to_jsonb(f)->>'father_employment_status' from public.families f where id='94000000-0000-0000-0000-000000000001'),'لا يعمل','father employment status persists');
select throws_ok($$select public.save_case_file('94000000-0000-0000-0000-000000000001','{"mother_name":"الأم","phone":"01012345678","father_employment_status":"لا يعمل","father_occupation":"محاسب"}'::jsonb,null)$$,'23514',null,'work type is rejected unless the person is marked as working');
select throws_ok($$select public.save_case_file('94000000-0000-0000-0000-000000000001','{"mother_name":"الأم","phone":"01012345678","father_national_id":"123"}'::jsonb,null)$$,'23514',null,'invalid parent national IDs are rejected');
reset role;
select set_config('request.jwt.claims','{"sub":"63000000-0000-0000-0000-000000000002","session_id":"73000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select date_of_birth from public.people where name='ريم'),'2008-12-31'::date,'family reader can see member birth date');
select is((select to_jsonb(p)->>'health_condition' from public.people p where name='كريم'),'إعاقة حركية','family reader can see individual health details');
select is((select to_jsonb(p)->>'health_status' from public.people p where name='كريم'),'عجز أو إعاقة','family reader can see individual health status');
select is((select to_jsonb(p)->>'employment_status' from public.people p where name='سلمى'),'يعمل','family reader can see individual employment status');
select throws_ok($$select public.add_family_member_profile('94000000-0000-0000-0000-000000000001','فرد','ابن','male','2010-01-01')$$,'42501',null,'read-only staff cannot add member profile');
select * from finish();
rollback;
